mapper.select:
SELECT USERID, USERNAME, RESPONSIBLE, USERPOSITION, EMAIL
FROM hdoc_user_infor
WHERE USERID = #{userid}

SELECT USERID, MARKET, `TYPE`, BU
FROM HDOC_MARKET_AUTH
WHERE USERID = #{userid}
AND `TYPE` IN (
    SELECT `FUNCTION` FROM HDOC_FUNCTION_AUTH WHERE USERID = #{userid}
)

SELECT DISTINCT u.USERID, u.USERNAME AS `user`,
    (SELECT GROUP_CONCAT(DISTINCT ma.MARKET ORDER BY ma.MARKET SEPARATOR ',')
     FROM HDOC_MARKET_AUTH ma WHERE ma.USERID = u.USERID

         AND ma.MARKET IN

             #{m}


    ) AS market
FROM hdoc_user_infor u
INNER JOIN HDOC_FUNCTION_AUTH fa ON u.USERID = fa.USERID
WHERE 1=1

    AND u.USERID = #{userid}


    AND u.USERNAME LIKE CONCAT('%', #{user}, '%')


    AND fa.FUNCTION = #{function}


    AND u.USERID IN (
        SELECT DISTINCT ma.USERID FROM HDOC_MARKET_AUTH ma
        WHERE ma.MARKET IN

            #{m}

    )

ORDER BY u.USERID
